Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

long long pattern[20];
int min_steps;

long long get_leading(long long num, int &length) {
    length = 0;
    while (num >= 10) {
        num /= 10;
        length++;
    }
    return num;
}

void search(long long current_value, int steps_taken) {
    if (steps_taken >= min_steps) return;
    if (current_value == 0) {
        min_steps = steps_taken;
        return;
    }
    int len;
    int lead_digit = get_leading(current_value, len);
    search(abs(current_value - pattern[len] * lead_digit), steps_taken + lead_digit * (len + 1));
    if (lead_digit - 1 > 0)
        search(abs(current_value - pattern[len] * (lead_digit - 1)), steps_taken + (lead_digit - 1) * (len + 1));
    if (lead_digit > 1)
        search(abs(pattern[len + 1] - current_value), steps_taken + (len + 2));
}

int main() {
    long long n;
    scanf("%lld", &n);
    pattern[0] = 1;
    for (int i = 1; i <= 18; i++) {
        pattern[i] = pattern[i - 1] * 10 + 1;
    }
    min_steps = 1e9;
    search(n, 0);
    printf("%d\n", min_steps);
    return 0;
}
